/**
 * Backend detection — static imports, open() tries in priority order
 */
import * as miniaudio from './backends/miniaudio.js'
import * as process_ from './backends/process.js'
import * as null_ from './backends/null.js'

const backends = [
  { name: 'miniaudio', ...miniaudio },
  { name: 'process', ...process_ },
  { name: 'null', ...null_ },
]

/** The first backend's outputs that can list them: [{ id, name, default }] */
export function devices(preference) {
  for (const b of preference ? backends.filter(b => b.name === preference) : backends) {
    try { return b.devices() } catch {}
  }
  return []
}

export function open(opts, preference) {
  const order = preference
    ? backends.filter(b => b.name === preference)
    : backends
  let lastErr

  for (const { name, open } of order) {
    try { return { name, device: open(opts) } }
    catch (e) { if (e.code === 'ENODEVICE') throw e; lastErr = e }   // no such device: another backend won't have it
  }

  throw new Error(
    'No audio backend available. Install @audio/speaker-* for your platform or run npm run build.' +
    (lastErr ? ` Last error: ${lastErr.message}` : '')
  )
}
